import{_ as o,o as t,c as s,a2 as n}from"./chunks/framework.CBxkvBm_.js";const y=JSON.parse('{"title":"SysML v2 & KerML (.sysml, .sysml2, .kerml)","description":"","frontmatter":{},"headers":[],"relativePath":"languages/sysml2.md","filePath":"languages/sysml2.md"}'),r={name:"languages/sysml2.md"};function i(d,e,c,a,l,g){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="sysml-v2-kerml-sysml-sysml2-kerml" tabindex="-1">SysML v2 &amp; KerML (<code>.sysml</code>, <code>.sysml2</code>, <code>.kerml</code>) <a class="header-anchor" href="#sysml-v2-kerml-sysml-sysml2-kerml" aria-label="Permalink to &quot;SysML v2 &amp; KerML (`.sysml`, `.sysml2`, `.kerml`)&quot;">​</a></h1><p><code>@modelscript/sysml2</code> (<code>languages/sysml2</code>) implements the OMG <strong>Systems Modeling Language v2 (SysML v2)</strong> and <strong>Kernel Modeling Language (KerML)</strong> textual notation, pairing a bundled KerML/SysML v2 standard library snapshot with a suite of formal verification, safety analysis, direct DAE compilation, and enterprise synchronization engines.</p><hr><h2 id="supported-extensions" tabindex="-1">Supported Extensions <a class="header-anchor" href="#supported-extensions" aria-label="Permalink to &quot;Supported Extensions&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Extension</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.sysml</code>, <code>.sysml2</code></td><td style="text-align:left;">OMG SysML v2 textual architecture, requirement, state, action, and verification models</td></tr><tr><td style="text-align:left;"><code>.kerml</code></td><td style="text-align:left;">OMG Kernel Modeling Language (KerML) metamodel &amp; library definitions</td></tr></tbody></table><hr><h2 id="supported-sysml-v2-constructs" tabindex="-1">Supported SysML v2 Constructs <a class="header-anchor" href="#supported-sysml-v2-constructs" aria-label="Permalink to &quot;Supported SysML v2 Constructs&quot;">​</a></h2><ul><li><strong>Structural Modeling</strong>: <code>package</code>, <code>part def</code>, <code>part</code>, <code>attribute def</code>, <code>attribute</code>, <code>item def</code>, <code>item</code>, <code>port def</code>, <code>port</code>, <code>connection def</code>, <code>connection</code>, <code>interface def</code>, <code>interface</code>, <code>flow</code>, <code>allocation def</code>, <code>allocate</code></li><li><strong>Behavioral &amp; State Modeling</strong>: <code>action def</code>, <code>action</code>, <code>state def</code>, <code>state</code>, <code>transition</code>, <code>First</code> / <code>then</code> succession flows, <code>fork</code>, <code>join</code>, <code>decide</code>, <code>merge</code>, <code> calc def</code>, <code>calc</code></li><li><strong>Requirements &amp; Verification</strong>: <code>requirement def</code>, <code>requirement</code>, <code>satisfy</code>, <code>verify</code>, <code>verification def</code>, <code>concern</code>, <code>stakeholder</code>, <code>view</code>, <code>viewpoint</code>, <code>constraint def</code>, <code>constraint</code>, <code>assume</code>, <code>require</code></li></ul><hr><h2 id="formal-verification-safety-analysis-engines" tabindex="-1">Formal Verification &amp; Safety Analysis Engines <a class="header-anchor" href="#formal-verification-safety-analysis-engines" aria-label="Permalink to &quot;Formal Verification &amp; Safety Analysis Engines&quot;">​</a></h2><p><code>@modelscript/sysml2</code> includes seven specialized formal verification modules in <code>languages/sysml2/src/</code>:</p><ol><li><strong>Activity Control-Flow &amp; Petri-Net Soundness (<code>activity-cfa.ts</code>, <code>activity-soundness.ts</code>, <code>activity-verifier.ts</code>)</strong>: <ul><li>Lowers SysML v2 <code>action def</code> successions (<code>first A then B</code>), <code>fork</code>/<code>join</code>, and <code>decide</code>/<code>merge</code> nodes into Workflow Nets (1-safe Petri nets).</li><li>Verifies <strong>Option to Complete</strong>, <strong>Proper Completion</strong>, <strong>No Dead Transitions</strong>, <strong>Lack of Synchronization</strong> (parallel branches converging into a <code>merge</code> instead of a <code>join</code>), and <strong>Deadlock at Join</strong> (exclusive <code>decide</code> branches converging into a <code>join</code>).</li></ul></li><li><strong>Decision Table Completeness &amp; Disjointness (<code>decision-table-verifier.ts</code>)</strong>: <ul><li>Analyzes guarded <code>decide</code> branches and requirement tables via interval covering and SMT/constraint checking to detect <strong>Missing Cases</strong> (uncovered input domain gaps) and <strong>Overlapping Rules</strong> (non-deterministic guard collisions).</li><li>Exposed via CLI: <code>npx msx verify-decisions architecture.sysml</code>.</li></ul></li><li><strong>Assume-Guarantee Contract Verification (<code>contract-verifier.ts</code>, <code>multidomain-contract-bridge.ts</code>)</strong>: <ul><li>Extracts <code>assume constraint { ... }</code> and <code>require constraint { ... }</code> blocks from <code>requirement def</code> and <code>part def</code> hierarchies.</li><li>Verifies <strong>Contract Compatibility</strong> ($\\bigwedge A_{\\text{env}} \\neq \\bot$) and <strong>Refinement Soundness</strong> across composite sub-parts ($A_{\\text{parent}} \\Rightarrow A_{\\text{child}}$ and $\\bigwedge G_{\\text{children}} \\Rightarrow G_{\\text{parent}}$), bridging directly into the Multi-Domain Theory Coordinator.</li></ul></li><li><strong>Hierarchical State Machine Verifier (<code>state-machine-verifier.ts</code>)</strong>: <ul><li>Checks <code>state def</code> machines for <strong>Unreachable States</strong>, <strong>Deadlock / Trap States</strong> (non-final states with no outgoing transitions), <strong>Non-Deterministic Transitions</strong> (overlapping guards on the same trigger event), and <strong>Missing Initial States</strong>.</li></ul></li><li><strong>Hybrid Automaton Flowpipe Bridge (<code>hybrid-flowpipe-bridge.ts</code>)</strong>: <ul><li>Couples discrete SysML v2 <code>state def</code> mode transitions with continuous Modelica DAE dynamics to compute Taylor-model / interval reachability flowpipes and verify that unsafe states are unreachable over time horizon $[0, T]$.</li></ul></li><li><strong>Fault Tree &amp; Physics-Informed Safety Analyzer (<code>safety-analyzer.ts</code>, <code>physics-safety-bridge.ts</code>)</strong>: <ul><li>Synthesizes Fault Trees from SysML v2 failure modes and interconnections, computes <strong>Minimal Cut Sets (MCS)</strong> via MOCUS/top-down boolean reduction, evaluates top-event failure probabilities, and cross-checks physical failure thresholds against simulated Modelica/FEA/CFD peak stresses and temperatures.</li></ul></li><li><strong>Boundary-Value &amp; MC/DC Test Vector Synthesizer (<code>boundary-test-synthesizer.ts</code>)</strong>: <ul><li>Automatically generates boundary-value ($x = c - \\epsilon, c, c + \\epsilon$) and Modified Condition/Decision Coverage (<strong>MC/DC</strong>) test vectors for every <code>requirement def</code> and <code>calc def</code> constraint.</li><li>Exposed via CLI: <code>npx msx generate-tests architecture.sysml</code>.</li></ul></li></ol><hr><h2 id="direct-sysml-v2-rightarrow-dae-lowering-enterprise-interchange" tabindex="-1">Direct SysML v2 $\\rightarrow$ DAE Lowering &amp; Enterprise Interchange <a class="header-anchor" href="#direct-sysml-v2-rightarrow-dae-lowering-enterprise-interchange" aria-label="Permalink to &quot;Direct SysML v2 $\\rightarrow$ DAE Lowering &amp; Enterprise Interchange&quot;">​</a></h2><ul><li><strong>Direct Arena DAE Lowering (<code>sysml2-dae-lowerer.ts</code>)</strong>: Compiles SysML v2 <code>calc def</code>, <code>constraint def</code>, <code>attribute</code> bindings, and <code>flow</code> connections directly into <code>@modelscript/runtime</code>&#39;s <code>DAEBuilder</code> without requiring an intermediate Modelica code-generation pass.</li><li><strong><code>.sysmlx</code> JSON-LD &amp; Container Export (<code>sysmlx-interchange.ts</code>, <code>sysml2-container-exporter.ts</code>)</strong>: Serializes and imports OMG SysML v2 REST/JSON-LD payloads (<code>.sysmlx</code>) and multi-artifact engineering containers.</li><li><strong>Enterprise MBSE Gateway (<code>enterprise-sync-gateway.ts</code>)</strong>: Synchronizes SysML v2 packages, elements, and cross-domain traceability links with <strong>Dassault Cameo Teamwork Cloud (TWC)</strong>, <strong>OpenMBEE MMS</strong>, and standard <strong>OMG SysML v2 REST API</strong> repositories (<code>npx msx sysml sync</code>).</li></ul><hr><h2 id="polyglot-tgg-rules-22-cross-domain-mappings" tabindex="-1">Polyglot TGG Rules (22 Cross-Domain Mappings) <a class="header-anchor" href="#polyglot-tgg-rules-22-cross-domain-mappings" aria-label="Permalink to &quot;Polyglot TGG Rules (22 Cross-Domain Mappings)&quot;">​</a></h2><p><code>@modelscript/sysml2</code> defines 22 bidirectional Triple Graph Grammar (TGG) rules in <code>languages/sysml2/src/language.ts</code> spanning <strong>Modelica</strong> (14 rules), <strong>OWL2</strong> (5 rules), and <strong>STEP</strong> (3 rules):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Target Language</th><th style="text-align:left;">Rule Names</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>modelica</code> (14 rules)</strong></td><td style="text-align:left;"><code>SysML2PartDefToModelicaModel</code>, <code>SysML2AttributeDefToModelicaType</code>, <code>SysML2PortDefToModelicaConnector</code>, <code>SysML2ConnectionDefToModelicaModel</code>, <code>SysML2ActionDefToModelicaBlock</code>, <code>SysML2ConstraintDefToModelicaBlock</code>, <code>SysML2RequirementDefToModelicaBlock</code>, <code>SysML2PartToModelicaComponent</code>, <code>SysML2AttributeToModelicaParameter</code>, <code>SysML2PortToModelicaConnector</code>, <code>SysML2ConnectionToModelicaConnect</code>, <code>SysML2FlowToModelicaConnect</code>, <code>SysML2StateToModelicaBlock</code>, <code>SysML2TransitionToModelicaWhen</code></td></tr><tr><td style="text-align:left;"><strong><code>owl2</code> (5 rules)</strong></td><td style="text-align:left;"><code>SysML2PartDefToOWL2Class</code>, <code>SysML2AttributeUsageToOWL2DataProperty</code>, <code>SysML2PortUsageToOWL2ObjectProperty</code>, <code>SysML2PartUsageToOWL2Individual</code>, <code>SysML2RequirementToOWL2Class</code></td></tr><tr><td style="text-align:left;"><strong><code>step</code> (3 rules)</strong></td><td style="text-align:left;"><code>SysML2PartDefToStepProduct</code>, <code>SysML2PartUsageToStepAssemblyUsage</code>, <code>SysML2AttributeToStepProperty</code></td></tr></tbody></table>',19)])])}const u=o(r,[["render",i]]);export{y as __pageData,u as default};
